prompt:
Implement the arena with one addition — aligned allocation:

```c
typedef struct { unsigned char *mem; size_t cap; size_t used; } arena_t;
void arena_init(arena_t *a, unsigned char *buf, size_t cap);
void *arena_alloc_aligned(arena_t *a, size_t n, size_t align);
size_t arena_used(const arena_t *a);
void arena_reset(arena_t *a);
```

`arena_alloc_aligned` first aligns the current offset up to `align` (power of two), then places the slice; returns NULL if it cannot fit. `arena_used` reports current `used`.

tests.code:
unsigned char buf[128];
arena_t a;
arena_init(&a, buf, sizeof buf);
unsigned char *p1 = arena_alloc_aligned(&a, 3, 8);
CHECK_EQ((int)(p1 - buf), 0);
unsigned char *p2 = arena_alloc_aligned(&a, 1, 8);
CHECK_EQ((int)(p2 - buf), 8);

unsigned char buf[128];
arena_t a;
arena_init(&a, buf, sizeof buf);
arena_alloc_aligned(&a, 3, 8);
arena_alloc_aligned(&a, 1, 8);
CHECK_EQ((long long)arena_used(&a), 9);

unsigned char buf[128];
arena_t a;
arena_init(&a, buf, sizeof buf);
CHECK_NULL(arena_alloc_aligned(&a, 200, 8));

unsigned char buf[128];
arena_t a;
arena_init(&a, buf, sizeof buf);
arena_alloc_aligned(&a, 40, 8);
arena_reset(&a);
CHECK_EQ((long long)arena_used(&a), 0);
CHECK_NOT_NULL(arena_alloc_aligned(&a, 128, 16));
